import{_ as t,o,c as r,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Sequence Flow — Remove Workspace Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-21-remove-workspace-member/sequence-flow.md","filePath":"feature/agency-workspace/3-4-21-remove-workspace-member/sequence-flow.md"}'),s={name:"feature/agency-workspace/3-4-21-remove-workspace-member/sequence-flow.md"};function i(c,e,d,l,n,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="sequence-flow-—-remove-workspace-member" tabindex="-1">Sequence Flow — Remove Workspace Member <a class="header-anchor" href="#sequence-flow-—-remove-workspace-member" aria-label="Permalink to &quot;Sequence Flow — Remove Workspace Member&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.21). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-23.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — the MANAGER of the Workspace, removing the member.</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding membership records.</li></ul><hr><h2 id="flow-a-—-remove-a-member-from-the-workspace" tabindex="-1">Flow A — Remove a member from the Workspace <a class="header-anchor" href="#flow-a-—-remove-a-member-from-the-workspace" aria-label="Permalink to &quot;Flow A — Remove a member from the Workspace&quot;">​</a></h2><ol><li>Client → System: on <code>/workspaces/:id/members</code>, choose Remove for a member and confirm in the dialog.</li><li>System: check the caller&#39;s role in the Workspace before handling the request — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System → Database: look up the member; a member that does not exist, is not active, or belongs to another Workspace is rejected with 404 <code>NOT_FOUND</code>.</li><li>System: apply the last-MANAGER guard: <ul><li>When the member&#39;s role is not MANAGER, continue.</li><li>When the member&#39;s role is MANAGER, count the Workspace&#39;s active MANAGERs; a count of one or fewer is rejected with 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>.</li></ul></li><li>System: mark the membership inactive and record the update timestamp.</li><li>System → Database: write the deactivated membership.</li><li>System → Client: confirmation that the membership has been deactivated.</li><li>Client: refresh the member table; the member disappears from the active list. The member&#39;s Agency membership is untouched, so they remain in the Agency and in any other Workspace they take part in.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Remove</td><td>Caller is not the MANAGER of the Workspace</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Remove</td><td>Member does not exist, is not active, or belongs to another Workspace</td><td>404</td><td><code>NOT_FOUND</code></td></tr><tr><td>Remove</td><td>Member is the only active MANAGER of the Workspace</td><td>409</td><td><code>LAST_MANAGER_CANNOT_BE_REMOVED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The last-MANAGER guard (<code>assertNotLastManager</code> in <code>WorkspaceServiceImpl</code>) is shared with FR 3.4.16 Leave Workspace (<code>leaveWorkspace</code>) and FR 3.4.20 Update Workspace Member Role (<code>updateMemberRole</code>). <code>ErrorCode.java</code> also defines an unused <code>LAST_OWNER_CANNOT_BE_REMOVED</code> (409) that no code path throws.</li><li>Removal is a soft delete; the membership row is retained with an inactive flag.</li><li>The member&#39;s Agency membership is never touched.</li></ul>',12)])])}const b=t(s,[["render",i]]);export{p as __pageData,b as default};
